-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.demonhunter.devourer.Name"] = "Blizzard Assisted"
L["rm.retail.demonhunter.devourer.Description"] = "Recommended for Devourer. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel Void Ray. Alongside it, reminders for what the assistant leaves to you: Void Metamorphosis, The Hunt and Voidblade whenever they are ready in combat, Disrupt on an interruptible cast, and Blur whenever it is ready in combat. Enemy casts are hidden in combat, so Disrupt lights only where the game shows them; health is hidden on Retail, so when to use Blur is your call."
L["rm.retail.demonhunter.devourer.guide.Name"] = "Reference (Icy Veins)"
L["rm.retail.demonhunter.devourer.guide.Description"] = "Reference only, off by default: Icy Veins' Annihilator priority. Most of your buffs are hidden in Midnight combat, so it cannot run there; Fury is hidden on Retail, so Void Ray waits only for its cost. Outside Void Metamorphosis: Consume on Soulburst, Reap, Soul Immolation when it is not burning, Voidblade and The Hunt once Void Metamorphosis is ready, Void Metamorphosis, Hungering Slash, Void Ray, Consume. Inside it: Devour on Soulburst, Void Ray, the Void-Scarred strikes if you have them, Collapsing Star, Cull, Devour, Soul Immolation. Rotation Master cannot count Soul Fragments, so Reap and Cull go on cooldown. Reminders: Disrupt and Blur."
L["rm.retail.demonhunter.devourer.simc.Name"] = "Reference (SimulationCraft)"
L["rm.retail.demonhunter.devourer.simc.Description"] = "Reference only, off by default: SimulationCraft's Annihilator list, which enters Void Metamorphosis as soon as it is ready. Hidden combat data keeps it from running in Midnight combat. Outside: Voidblade with Devourer's Bite on up to three enemies and a full Void Metamorphosis, Void Metamorphosis, Consume on Soulburst, Reap, Void Ray, Soul Immolation on packs, Consume. Inside: Devour on Soulburst against one target, The Hunt and Voidblade with Devourer's Bite, Void Ray on packs, Collapsing Star, Cull, Void Ray, Soul Immolation, Devour. Reminders: Disrupt and Blur."
L["rm.retail.demonhunter.havoc.Name"] = "Blizzard Assisted"
L["rm.retail.demonhunter.havoc.Description"] = "Recommended for Havoc. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what the game's assistant leaves to you: Metamorphosis and The Hunt in combat, Vengeful Retreat if you have Inertia or Exergy, Disrupt on an interruptible cast, and Blur whenever it is ready in combat. Enemy casts are hidden in combat, so Disrupt lights only where the game shows them; health is hidden on Retail, so when to use Blur is your call. Movement, Darkness and trinkets stay with you."
L["rm.retail.demonhunter.havoc.guide.Name"] = "Reference (Icy Veins, SimulationCraft and Wowhead)"
L["rm.retail.demonhunter.havoc.guide.Description"] = "Reference only, off by default: the guides' Havoc priority. Your procs, Metamorphosis and Essence Break are hidden from addons in Midnight combat, so this list cannot run there; read it, or clone it to experiment. Fury is hidden on Retail, so Felblade does not wait for room. Aldrachi Reaver: Reaver's Glaive when neither Rending Strike nor Glaive Flurry is up, Chaos Strike on Rending Strike. Fel-Scarred: Essence Break, Blade Dance and Chaos Strike in Metamorphosis. Then Blade Dance and Chaos Strike inside Essence Break, Immolation Aura at two charges, Eye Beam, Felblade for Inertia, Essence Break when Eye Beam is over 4 seconds away, Blade Dance, Immolation Aura on two enemies, Chaos Strike, Felblade, Immolation Aura, Throw Glaive, Fel Rush. Reminders: Metamorphosis once Eye Beam and Blade Dance are spent, The Hunt, Vengeful Retreat, plus Disrupt and Blur."
L["rm.retail.demonhunter.initial.Name"] = "Blizzard Assisted"
L["rm.retail.demonhunter.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Demon Hunter's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Demon Hunter premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.demonhunter.vengeance.Name"] = "Blizzard Assisted"
L["rm.retail.demonhunter.vengeance.Description"] = "Recommended for Vengeance. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what the assistant leaves to you: Demon Spikes, Fiery Brand, Fel Devastation and Metamorphosis whenever they are ready in combat, Disrupt on an interruptible cast, and Blur whenever it is ready in combat. Enemy casts are hidden in combat, so Disrupt lights only where the game shows them; health is hidden on Retail, so when to use Blur is your call. Infernal Strike, Darkness, taunts and trinkets stay with you."
L["rm.retail.demonhunter.vengeance.guide.Name"] = "Reference (Wowhead and Icy Veins)"
L["rm.retail.demonhunter.vengeance.guide.Description"] = "Reference only, off by default: Wowhead's Vengeance order with Icy Veins' hero-tree goals. Your buffs are hidden in Midnight combat, so it cannot run there; Fury is hidden on Retail, so spenders wait only for their cost and builders do not avoid capping. Aldrachi Reaver: Reaver's Glaive, Fracture on Rending Strike, Soul Cleave on Glaive Flurry. Then Fracture at full charges, Spirit Bomb on three or more enemies, Immolation Aura, Sigil of Flame, Soul Cleave against one target, Fel Devastation, Soul Cleave, Fracture, Felblade, Throw Glaive. Rotation Master cannot count Soul Fragments, so Spirit Bomb follows the enemy count. Reminders: Demon Spikes when it is down, Metamorphosis, Fiery Brand, Sigil of Spite, Soul Carver (Infernal Strike at two charges is off), plus Disrupt and Blur."
L["rm.retail.demonhunter.vengeance.simc.Name"] = "Reference (SimulationCraft)"
L["rm.retail.demonhunter.vengeance.simc.Description"] = "Reference only, off by default: SimulationCraft's Vengeance lists. Hidden combat data keeps it from running in Midnight combat, and Fury is hidden on Retail, so its Fury thresholds are left out. Aldrachi Reaver: Sigil of Flame and Immolation Aura first, Metamorphosis, the Reaver's Glaive cycle with Felblade, Fiery Brand, Sigil of Spite, Spirit Bomb on packs, Soul Carver in Fiery Demise, then Fracture, Soul Cleave, Felblade, Fel Devastation. Annihilator: spend a ready Voidfall with Spirit Bomb or Soul Cleave, Fracture at two Voidfall stacks, Metamorphosis, Spirit Bomb, Sigil of Spite, Fracture at full charges, Immolation Aura, Sigil of Flame, Fracture, Soul Cleave, Felblade, Throw Glaive. Reminders: Demon Spikes, Disrupt, Blur."
